-- Day 30: prompt_cards exercise (replaces program_completion); voiceover updated.
-- Timed_text from Whisper base.en word-level; overrides applied for cues >100c.

begin;

-- Day 23: Your Visualization Board
update public.lessons set
  duration_seconds = 225,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_23/lesson_23_seg_01.mp3"],"total_audio_seconds":106.45,"timed_text":[{"start_s":0.0,"text":"A23."},{"start_s":1.46,"text":"Today we''re doing something I do with every athlete I work with."},{"start_s":13.88,"text":"So I want you to go somewhere most athletes never let themselves go."},{"start_s":18.42,"text":"Five to ten years from now — the life where the work paid off."},{"start_s":24.78,"text":"Think about that."},{"start_s":25.58,"text":"Where the goals you''ve been chasing actually happened."},{"start_s":32.46,"text":"Not a vague idea of success."},{"start_s":35.08,"text":"A very specific detail picture, right?"},{"start_s":39.08,"text":"So think about this."},{"start_s":41.02,"text":"Where are you?"},{"start_s":42.5,"text":"What does your surroundings look like?"},{"start_s":45.74,"text":"What do you see?"},{"start_s":47.96,"text":"What do you smell?"},{"start_s":50.02,"text":"What do you hear?"},{"start_s":52.26,"text":"What can you taste?"},{"start_s":54.46,"text":"What are the specific things you observe that tell you?"},{"start_s":58.26,"text":"This is it."},{"start_s":59.96,"text":"This is the life I built."},{"start_s":61.74,"text":"Sit inside that moment and feel it."},{"start_s":64.36,"text":"Now what it looks like, what it actually feels like."},{"start_s":68.6,"text":"Pride, satisfaction, gratitude — you didn''t quit when it was hard."},{"start_s":75.48,"text":"Why is this goal significant to you?"},{"start_s":77.5,"text":"Why does reaching this version of your life matter?"},{"start_s":81.08,"text":"Then, rewind."},{"start_s":83.34,"text":"Come all the way back to today."},{"start_s":85.86,"text":"The goal is there."},{"start_s":87.52,"text":"What is one step you can take today that moves the needle?"},{"start_s":97.08,"text":"On your screen, you''ll build this visualization in your journal."},{"start_s":100.62,"text":"So take your time with each prompt."},{"start_s":102.76,"text":"This is one of the most important things we''ve done in this program."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Time frame and goal — five to ten years from now, what have you achieved? Write the specific goal and exactly when it happens.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"The environment — describe exactly where you are. What do you see, smell, hear, taste, and observe around you? Build every detail.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"The feeling — you''ve reached it. What are the specific emotions you feel knowing you accomplished this? Describe the pride, the satisfaction, the gratitude. Why is this moment significant to you specifically?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Rewind to today. One step. What is one single thing you can do today that moves the needle toward that moment?","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_23/lesson_23_seg_02.mp3"],"total_audio_seconds":19.23,"timed_text":[{"start_s":0.0,"text":"That visualization lives in your journal. Come back to it."},{"start_s":12.14,"text":"The moment you just build, that''s what all of this is for."},{"start_s":16.2,"text":"And after you finish, day 23 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000023';

-- Day 30: The Evidence
update public.lessons set
  duration_seconds = 294,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_30/lesson_30_seg_01.mp3"],"total_audio_seconds":93.02,"timed_text":[{"start_s":0.0,"text":"Day 30, you made it."},{"start_s":2.54,"text":"You don''t want to gloss over that, okay?"},{"start_s":5.22,"text":"Most people quit around Day 8 or 15, when it starts feeling like work."},{"start_s":12.58,"text":"But you kept showing up every single day and that is not a small thing."},{"start_s":17.98,"text":"Think about where you were when you started this, what you didn''t have yet."},{"start_s":22.46,"text":"No reset word, no If-Then plan, no evidence log, no traffic light system."},{"start_s":38.04,"text":"No connection to your why."},{"start_s":40.64,"text":"You have all of that now."},{"start_s":42.44,"text":"Not because someone gave it to you — you built it, rep by rep, day by day."},{"start_s":50.08,"text":"The question to carry forward: the one that keeps athletes growing."},{"start_s":60.76,"text":"Not how much did I improve, what''s the next step?"},{"start_s":64.62,"text":"Take it into every season, every competition, every time you plateau."},{"start_s":70.72,"text":"Move forward."},{"start_s":72.86,"text":"Before you journal — go back to your Day 23 visualization and read it."},{"start_s":80.78,"text":"Sit inside that moment again. Then read your evidence log — every entry."},{"start_s":87.82,"text":"See what you''ve already done."},{"start_s":89.8,"text":"Then come back and write your last entry."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Open your Day 23 journal entry — your five to ten year visualization. Read it. Let yourself feel it again.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Now open your evidence log. Read every entry from the beginning.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"The distance between that visualization and where you stand right now? That''s the work. And you''ve already started closing it.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What''s next?","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_30/lesson_30_seg_02.mp3"],"total_audio_seconds":41.59,"timed_text":[{"start_s":0.0,"text":"You don''t need a score to know what changed."},{"start_s":2.76,"text":"You know it in how you showed up, how you handled the last competition."},{"start_s":14.86,"text":"That''s the evidence."},{"start_s":16.66,"text":"Keep the log, run the routine, use the tools, build on your why."},{"start_s":24.92,"text":"When it gets hard, you''ve been here before and came out with a plan."},{"start_s":35.4,"text":"Programs complete, but the training is it."},{"start_s":38.82,"text":"Go compete like it."},{"start_s":40.32,"text":"Stay relentless."}]},{"type":"journal_prompt","prompt":"What is different about the way you think about competing now compared to where you started? What does the next chapter look like — and what''s your first move?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000030';

commit;